#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = RadiationEquivalentDose::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            RadiationEquivalentDose::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in RadiationEquivalentDoseUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        RadiationEquivalentDose::from_base(0.0).auto_unit().unit,
        RadiationEquivalentDoseUnit::Sievert
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "Sv".parse::<RadiationEquivalentDoseUnit>(),
        Ok(RadiationEquivalentDoseUnit::Sievert)
    );
    assert_eq!(
        format!("2.5 {}", "Sv").parse::<RadiationEquivalentDose>(),
        Ok(RadiationEquivalentDose::new(
            2.5,
            RadiationEquivalentDoseUnit::Sievert
        ))
    );
    assert_eq!(
        "nSv".parse::<RadiationEquivalentDoseUnit>(),
        Ok(RadiationEquivalentDoseUnit::Nanosievert)
    );
    assert_eq!(
        format!("2.5 {}", "nSv").parse::<RadiationEquivalentDose>(),
        Ok(RadiationEquivalentDose::new(
            2.5,
            RadiationEquivalentDoseUnit::Nanosievert
        ))
    );
    assert_eq!(
        "µSv".parse::<RadiationEquivalentDoseUnit>(),
        Ok(RadiationEquivalentDoseUnit::Microsievert)
    );
    assert_eq!(
        format!("2.5 {}", "µSv").parse::<RadiationEquivalentDose>(),
        Ok(RadiationEquivalentDose::new(
            2.5,
            RadiationEquivalentDoseUnit::Microsievert
        ))
    );
    assert_eq!(
        "mSv".parse::<RadiationEquivalentDoseUnit>(),
        Ok(RadiationEquivalentDoseUnit::Millisievert)
    );
    assert_eq!(
        format!("2.5 {}", "mSv").parse::<RadiationEquivalentDose>(),
        Ok(RadiationEquivalentDose::new(
            2.5,
            RadiationEquivalentDoseUnit::Millisievert
        ))
    );
    assert_eq!(
        "rem".parse::<RadiationEquivalentDoseUnit>(),
        Ok(RadiationEquivalentDoseUnit::RoentgenEquivalentMan)
    );
    assert_eq!(
        format!("2.5 {}", "rem").parse::<RadiationEquivalentDose>(),
        Ok(RadiationEquivalentDose::new(
            2.5,
            RadiationEquivalentDoseUnit::RoentgenEquivalentMan
        ))
    );
    assert_eq!(
        "mrem".parse::<RadiationEquivalentDoseUnit>(),
        Ok(RadiationEquivalentDoseUnit::MilliroentgenEquivalentMan)
    );
    assert_eq!(
        format!("2.5 {}", "mrem").parse::<RadiationEquivalentDose>(),
        Ok(RadiationEquivalentDose::new(
            2.5,
            RadiationEquivalentDoseUnit::MilliroentgenEquivalentMan
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<RadiationEquivalentDose>(),
        Err(ParseError::UnknownUnit)
    );
}

